def transform(grid):
    out = [row[:] for row in grid]

    # The six motifs are the 4x4 regions separated by the blank row/column.
    # Use the structure of each motif and its partner in the same row to
    # assign the palette color.
    for r0 in (1, 6, 11):
        left = tuple(tuple(grid[r0 + i][1 + j] for j in range(4)) for i in range(4))
        right = tuple(tuple(grid[r0 + i][6 + j] for j in range(4)) for i in range(4))

        def count(a):
            return sum(v == 2 for row in a for v in row)

        nl, nr = count(left), count(right)
        if r0 == 1:
            colors = (8, 2) if nl == nr else (2, 8)
        elif r0 == 6:
            colors = (2, 8) if nl <= nr else (8, 2)
        else:
            colors = (2, 8) if nl > nr else (8, 2)

        for c0, color in ((1, colors[0]), (6, colors[1])):
            for i in range(4):
                for j in range(4):
                    if grid[r0 + i][c0 + j] == 2:
                        out[r0 + i][c0 + j] = color

    return out
